var i=[{title:`Vorteile`,text:`Jede Hand trägt ihre eigene Last, was einseitige Arbeit praktisch macht und Griffwinkel erlaubt, die eine feste Stange nicht bietet. Ein einarmiges Rudern oder Drücken mit einem Arm kann Unterschiede in der Kontrolle zwischen deinen Seiten zeigen. Kurzhanteln passen oft besser in kleine Räume als ein vollständiger Langhantelaufbau, auch wenn die Sprünge zwischen den Gewichten groß oder die Auswahl begrenzt sein kann.`},{title:`Dein Gewicht wählen`,text:`Wähle ein Paar oder eine einzelne Kurzhantel, mit der du deine Zielwiederholungen mit stabiler Bewegung und einigen Wiederholungen in Reserve schaffst. Als Anfänger brauchst du vielleicht unterschiedliche Lasten für Rudern, Curls und Drücken. Wenn das nächsthöhere Gewicht zu schwer ist, füge zuerst Wiederholungen, Bewegungsumfang oder Kontrolle mit der leichteren hinzu.`},{title:`Sicher in Position kommen`,text:`Setze dich für Bankdrücken mit den Kurzhanteln sicher gehalten nahe an den Oberschenkeln hin, lege dich kontrolliert zurück und bringe die Gewichte in Position, ohne sie zu schleudern. Nimm bei Hebungen im Stehen die Gewichte mit Beinen und Rumpf in stabiler Position auf. Lass Gewichte nicht fallen, wo sie dir auf die Füße springen, den Boden beschädigen oder jemanden treffen könnten.`},{title:`Häufige Anwendungen`,text:`Goblet-Kniebeugen und rumänisches Kreuzheben mit Kurzhanteln trainieren den Unterkörper, gestützte Ruderzüge und Drücken decken den Oberkörper ab, und Tragen baut Griff und Rumpfkontrolle auf. Wenn du nur eine Kurzhantel hast, nutze sie für einseitige Bewegungen.`},{title:`TrainUp nutzen`,text:`Gib im Profil die Kurzhantelgewichte an, die du besitzt. Dein Plan wählt Übungen, die zu deiner Ausrüstung, deinem Platz und deiner Deckenhöhe passen. Er schreibt keine Gewichte vor, du wählst die Last also selbst. Wenn du deine Lasten nach einem Training notierst, schreibe sie jedes Mal gleich auf, etwa „12 kg pro Hand“.`}];var t=[{label:`Mayo Clinic: freie Gewichte gegenüber Maschinen`,url:`https://www.augustahealth.com/answer/weight-training-free-weights-vs-machine-weights/`},{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: Technik beim Krafttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};